1	"use client";
2	
3	import { useState } from "react";
4	import { useQuery } from "@tanstack/react-query";
5	import { supabase } from "@/integrations/supabase/client";
6	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
7	import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
8	import { Button } from "@/components/ui/button";
9	import { ChevronLeft, ChevronRight, Download } from "lucide-react";
10	import { exportToCSV } from "@/lib/csvExport";
11	
12	const PAGE_SIZE = 20;
13	
14	const UsageLogsTab = () => {
15	  const [page, setPage] = useState(0);
16	
17	  // Fetch user email map
18	  const { data: userMap } = useQuery({
19	    queryKey: ["admin_users"],
20	    queryFn: async () => {
21	      const { data, error } = await supabase.functions.invoke("admin-users", { method: "GET" });
22	      if (error) throw error;
23	      if (!Array.isArray(data)) throw new Error(data?.error || "Failed to load users");
24	      const map: Record<string, string> = {};
25	      data.forEach((u: any) => { map[u.id] = u.email; });
26	      return map;
27	    },
28	    staleTime: 5 * 60 * 1000,
29	  });
30	
31	  const { data } = useQuery({
32	    queryKey: ["admin_usage_logs", page],
33	    queryFn: async () => {
34	      const from = page * PAGE_SIZE;
35	      const to = from + PAGE_SIZE - 1;
36	      const { data, error, count } = await supabase
37	        .from("usage_logs")
38	        .select("*", { count: "exact" })
39	        .order("created_at", { ascending: false })
40	        .range(from, to);
41	      if (error) throw error;
42	      return { logs: data, total: count ?? 0 };
43	    },
44	  });
45	
46	  const totalPages = Math.ceil((data?.total ?? 0) / PAGE_SIZE);
47	
48	  const handleExport = () => {
49	    if (!data?.logs?.length) return;
50	    const rows = data.logs.map((l: any) => ({
51	      user: userMap?.[l.user_id] || l.user_id,
52	      job_id: l.job_id || "",
53	      credits_used: l.credits_used,
54	      date: new Date(l.created_at).toISOString(),
55	    }));
56	    exportToCSV(rows, "usage-logs");
57	  };
58	
59	  return (
60	    <Card>
61	      <CardHeader className="flex flex-row items-center justify-between pb-3">
62	        <CardTitle className="text-lg">Usage Logs</CardTitle>
63	        <div className="flex items-center gap-3">
64	          <Button variant="outline" size="sm" onClick={handleExport} disabled={!data?.logs?.length}>
65	            <Download className="h-4 w-4 mr-1" />CSV
66	          </Button>
67	          <div className="flex items-center gap-2 text-sm text-muted-foreground">
68	            Page {page + 1} of {Math.max(totalPages, 1)}
69	            <Button variant="outline" size="icon" className="h-7 w-7" disabled={page === 0} onClick={() => setPage(p => p - 1)}>
70	              <ChevronLeft className="h-3.5 w-3.5" />
71	            </Button>
72	            <Button variant="outline" size="icon" className="h-7 w-7" disabled={page >= totalPages - 1} onClick={() => setPage(p => p + 1)}>
73	              <ChevronRight className="h-3.5 w-3.5" />
74	            </Button>
75	          </div>
76	        </div>
77	      </CardHeader>
78	      <CardContent className="p-0">
79	        <Table>
80	          <TableHeader>
81	            <TableRow>
82	              <TableHead>User</TableHead>
83	              <TableHead>Job ID</TableHead>
84	              <TableHead>Credits Used</TableHead>
85	              <TableHead>Date</TableHead>
86	            </TableRow>
87	          </TableHeader>
88	          <TableBody>
89	            {data?.logs?.map((l: any) => (
90	              <TableRow key={l.id}>
91	                <TableCell className="text-sm" title={l.user_id}>
92	                  {userMap?.[l.user_id] || l.user_id?.slice(0, 8) + "…"}
93	                </TableCell>
94	                <TableCell className="font-mono text-xs">{l.job_id?.slice(0, 8) ?? "—"}</TableCell>
95	                <TableCell>{l.credits_used}</TableCell>
96	                <TableCell className="text-sm">{new Date(l.created_at).toLocaleString()}</TableCell>
97	              </TableRow>
98	            ))}
99	          </TableBody>
100	        </Table>
101	      </CardContent>
102	    </Card>
103	  );
104	};
105	
106	export default UsageLogsTab;
